/* GreenBean Coffee — Design System */

/* ===== CSS Variables ===== */
:root {
  --green-primary: #00824A;
  --green-dark: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF8EF;
  --white: #FFFFFF;
  --text-dark: #1A1A1A;
  --text-medium: #5A5A5A;
  --text-light: #8A8A8A;
  --border: #E5E5E5;
  --shadow-soft: 0 4px 20px rgba(0,0,0,0.08);
  --shadow-hover: 0 8px 30px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --transition: 0.3s ease;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'DM Sans', 'Inter', sans-serif;
  --max-width: 1200px;
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--text-dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  text-decoration: none;
  color: inherit;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 20px;
}

.section {
  padding: 80px 0;
}

.section--cream {
  background: var(--cream-light);
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 1rem;
  transition: all var(--transition);
}

.btn--primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--green-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.btn--secondary {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn--secondary:hover {
  background: var(--green-primary);
  color: var(--white);
}

.btn--light {
  background: var(--white);
  color: var(--green-dark);
}

.btn--light:hover {
  background: var(--cream);
}

.btn--ghost {
  background: transparent;
  color: var(--text-dark);
  padding: 10px 16px;
}

.btn--ghost:hover {
  background: rgba(0,0,0,0.05);
  border-radius: var(--radius-sm);
}

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: 0 20px;
}

.header__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--green-primary);
}

.header__logo svg {
  width: 36px;
  height: 36px;
}

.header__nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.header__nav a {
  font-weight: 500;
  color: var(--text-dark);
  padding: 8px 0;
  position: relative;
  transition: color var(--transition);
}

.header__nav a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition);
}

.header__nav a:hover {
  color: var(--green-primary);
}

.header__nav a:hover::after {
  width: 100%;
}

.header__actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header__menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.header__menu-btn span {
  width: 24px;
  height: 2px;
  background: var(--text-dark);
  transition: var(--transition);
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--green-dark) 0%, var(--green-primary) 100%);
  color: var(--white);
  padding: 100px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.hero__content {
  position: relative;
  z-index: 1;
}

.hero h1 {
  margin-bottom: 20px;
  color: var(--white);
}

.hero .btn--light {
  margin-top: 30px;
}

/* ===== Cards ===== */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.card__image {
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: var(--radius-md);
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
}

.card__tag {
  display: inline-block;
  padding: 6px 12px;
  background: var(--green-primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  margin-bottom: 12px;
}

.card__title {
  margin-bottom: 8px;
  color: var(--text-dark);
}

.card__text {
  color: var(--text-medium);
  margin-bottom: 16px;
  font-size: 0.95rem;
}

/* ===== Product Highlights ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.product-card__image {
  width: 100%;
  height: 220px;
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}

.product-card__content {
  padding: 24px;
}

.product-card__title {
  margin-bottom: 8px;
}

.product-card__text {
  color: var(--text-medium);
  font-size: 0.9rem;
  margin-bottom: 16px;
}

/* ===== Promo Section ===== */
.promo {
  background: var(--green-primary);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 60px 40px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.promo--reverse {
  background: var(--cream);
  color: var(--text-dark);
}

.promo__content h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.promo--reverse .promo__content h2 {
  color: var(--green-dark);
}

.promo__content p {
  opacity: 0.9;
  margin-bottom: 24px;
}

.promo__image {
  font-size: 8rem;
  text-align: center;
}

/* ===== Footer ===== */
.footer {
  background: var(--green-dark);
  color: var(--white);
  padding: 60px 0 0;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer__col h4 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 1rem;
}

.footer__col ul li {
  margin-bottom: 10px;
}

.footer__col a {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer__col a:hover {
  color: var(--white);
}

.footer__bottom {
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer__bottom p {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.6);
}

.footer__social {
  display: flex;
  gap: 16px;
}

.footer__social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  transition: background var(--transition);
}

.footer__social a:hover {
  background: var(--green-primary);
}

/* ===== Footer Accordion (Mobile) ===== */
.footer__accordion {
  display: none;
}

.footer__accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer__accordion-header {
  width: 100%;
  padding: 16px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--white);
  font-weight: 600;
}

.footer__accordion-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
}

.footer__accordion-item.active .footer__accordion-header svg {
  transform: rotate(180deg);
}

.footer__accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition);
}

.footer__accordion-item.active .footer__accordion-content {
  max-height: 300px;
}

.footer__accordion-content ul li {
  padding: 8px 0;
}

.footer__accordion-content a {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  padding: 20px;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  z-index: 1000;
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-banner__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}

.cookie-banner__text {
  flex: 1;
  min-width: 300px;
}

.cookie-banner__text h4 {
  margin-bottom: 4px;
}

.cookie-banner__text p {
  font-size: 0.9rem;
  color: var(--text-medium);
}

.cookie-banner__actions {
  display: flex;
  gap: 12px;
}

/* ===== Menu Page Styles ===== */
.breadcrumb {
  padding: 20px 0;
  font-size: 0.9rem;
  color: var(--text-medium);
}

.breadcrumb a {
  color: var(--green-primary);
}

.breadcrumb span {
  margin: 0 8px;
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 40px;
  padding: 40px 0;
}

.menu-sidebar {
  position: sticky;
  top: 100px;
  height: fit-content;
}

.menu-sidebar__title {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-light);
  margin-bottom: 12px;
  padding-left: 16px;
}

.menu-sidebar__section {
  margin-bottom: 32px;
}

.menu-sidebar nav a {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-dark);
  font-size: 0.95rem;
  transition: all var(--transition);
}

.menu-sidebar nav a:hover,
.menu-sidebar nav a.active {
  background: var(--green-primary);
  color: var(--white);
}

.menu-sidebar nav a .emoji {
  font-size: 1.2rem;
}

.menu-content {
  min-height: 600px;
}

.menu-category {
  margin-bottom: 60px;
}

.menu-category h2 {
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--cream);
}

.menu-items {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}

.menu-item {
  padding: 20px;
  border-radius: var(--radius-md);
  background: var(--white);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.menu-item:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-soft);
}

.menu-item__name {
  font-weight: 600;
  margin-bottom: 4px;
}

.menu-item__desc {
  font-size: 0.85rem;
  color: var(--text-medium);
}

/* ===== Rewards Page Styles ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--green-dark) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}

.rewards-hero h1 {
  color: var(--white);
  margin-bottom: 16px;
}

.rewards-hero p {
  opacity: 0.9;
  max-width: 600px;
  margin: 0 auto;
}

.how-it-works {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}

.how-step {
  text-align: center;
  padding: 32px;
}

.how-step__number {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--cream);
  color: var(--green-dark);
  font-size: 1.5rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.how-step h3 {
  margin-bottom: 12px;
}

.how-step p {
  color: var(--text-medium);
  font-size: 0.95rem;
}

.status-tiers {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.tier-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  border: 2px solid transparent;
  transition: all var(--transition);
}

.tier-card:hover {
  transform: translateY(-4px);
}

.tier-card--green {
  border-color: var(--green-primary);
}

.tier-card--gold {
  border-color: #D4AF37;
  background: linear-gradient(to bottom, #FFFDF5, var(--white));
}

.tier-card--reserve {
  border-color: #8B7355;
  background: linear-gradient(to bottom, #F5F0EB, var(--white));
}

.tier-card__badge {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.tier-card--green .tier-card__badge {
  background: var(--green-primary);
}

.tier-card--gold .tier-card__badge {
  background: linear-gradient(135deg, #D4AF37, #FFD700);
}

.tier-card--reserve .tier-card__badge {
  background: linear-gradient(135deg, #8B7355, #A08060);
}

.tier-card__name {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.tier-card__threshold {
  font-size: 0.9rem;
  color: var(--text-medium);
  margin-bottom: 20px;
}

.tier-card ul {
  text-align: left;
}

.tier-card ul li {
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.9rem;
  color: var(--text-medium);
}

.tier-card ul li:last-child {
  border-bottom: none;
}

/* Redemption Tabs */
.redemption-levels {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: 40px;
}

.redemption-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  border-bottom: 2px solid var(--border);
  padding-bottom: 16px;
}

.redemption-tab {
  padding: 12px 24px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-medium);
  background: var(--white);
  border: 2px solid var(--border);
  transition: all var(--transition);
}

.redemption-tab:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.redemption-tab.active {
  background: var(--green-primary);
  color: var(--white);
  border-color: var(--green-primary);
}

.redemption-content {
  display: none;
  animation: fadeIn 0.3s ease;
}

.redemption-content.active {
  display: block;
}

.redemption-content__header {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 24px;
}

.redemption-content__icon {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  box-shadow: var(--shadow-soft);
}

.redemption-content__stars {
  font-size: 2rem;
  font-weight: 700;
  color: var(--green-primary);
}

.redemption-content__reward {
  font-size: 1.2rem;
  color: var(--text-medium);
}

.redemption-items {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 16px;
}

.redemption-item {
  background: var(--white);
  padding: 20px;
  border-radius: var(--radius-md);
  display: flex;
  gap: 16px;
  align-items: center;
  box-shadow: var(--shadow-soft);
}

.redemption-item__emoji {
  font-size: 2rem;
  width: 50px;
  height: 50px;
  background: var(--cream-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.redemption-item__text h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.redemption-item__text p {
  font-size: 0.85rem;
  color: var(--text-medium);
}

.partnerships {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.partnership-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  gap: 20px;
  align-items: center;
  box-shadow: var(--shadow-soft);
}

.partnership-card__icon {
  font-size: 3rem;
  width: 80px;
  height: 80px;
  background: var(--cream-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.partnership-card h3 {
  margin-bottom: 8px;
}

.partnership-card p {
  color: var(--text-medium);
  font-size: 0.9rem;
}

.app-download {
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 60px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.app-download__content h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.app-download__content p {
  opacity: 0.9;
  margin-bottom: 24px;
}

.app-download__buttons {
  display: flex;
  gap: 16px;
}

.app-download__visual {
  font-size: 10rem;
  text-align: center;
}

.terms-link {
  text-align: center;
  color: var(--green-primary);
  text-decoration: underline;
}

/* ===== Gift Page Styles ===== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
  padding: 80px 0;
  text-align: center;
}

.gift-hero h1 {
  color: var(--green-dark);
}

.gift-hero p {
  color: var(--text-medium);
  max-width: 600px;
  margin: 16px auto 0;
}

.carousel-section {
  padding: 60px 0;
}

.carousel-section h2 {
  margin-bottom: 24px;
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: 20px;
  transition: transform 0.4s ease;
}

.carousel__card {
  flex: 0 0 calc(25% - 15px);
  min-width: 260px;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.carousel__card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.carousel__card-image {
  height: 160px;
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--cream) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.carousel__card-content {
  padding: 20px;
}

.carousel__card-content h4 {
  margin-bottom: 4px;
}

.carousel__card-content p {
  font-size: 0.85rem;
  color: var(--text-medium);
}

.carousel__nav {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
