/* ===== CSS Variables ===== */
:root {
  --green-primary: #00824A;
  --green-dark: #32462F;
  --cream: #F3CEA1;
  --cream-light: #FDF8EF;
  --white: #FFFFFF;
  --text-dark: #1A1A1A;
  --text-medium: #5A5A5A;
  --text-light: #8A8A8A;
  --border: #E5E5E5;
  --shadow-soft: 0 4px 20px rgba(0,0,0,0.08);
  --shadow-hover: 0 8px 30px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --transition: 0.3s ease;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'DM Sans', 'Inter', sans-serif;
  --max-width: 1200px;
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  color: var(--text-dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  text-decoration: none;
  color: inherit;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 20px;
}

.section {
  padding: 80px 0;
}

.section--cream {
  background: var(--cream-light);
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 1rem;
  transition: all var(--transition);
}

.btn--primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--green-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.btn--secondary {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn--secondary:hover {
  background: var(--green-primary);
  color: var(--white);
}

.btn--light {
  background: var(--white);
  color: var(--green-dark);
}

.btn--light:hover {
  background: var(--cream);
}

.btn--ghost {
  background: transparent;
  color: var(--text-dark);
  padding: 10px 16px;
}

.btn--ghost:hover {
  background: rgba(0,0,0,0.05);
  border-radius: var(--radius-sm);
}

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: 0 20px;
}

.header__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--green-primary);
}

.header__logo svg {
  width: 36px;
  height: 36px;
}

.header__nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.header__nav a {
  font-weight: 500;
  color: var(--text-dark);
  padding: 8px 0;
  position: relative;
  transition: color var(--transition);
}

.header__nav a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition);
}

.header__nav a:hover {
  color: var(--green-primary);
}

.header__nav a:hover::after {
  width: 100%;
}

.header__actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header__menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.header__menu-btn span {
  width: 24px;
  height: 2px;
  background: var(--text-dark);
  transition: var(--transition);
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--green-dark) 0%, var(--green-primary) 100%);
  color: var(--white);
  padding: 100px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.hero__content {
  position: relative;
  z-index: 1;
}

.hero h1 {
  margin-bottom: 20px;
  color: var(--white);
}

.hero .btn--light {
  margin-top: 30px;
}

/* ===== Cards ===== */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.card__image {
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: var(--radius-md);
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
}

.card__tag {
  display: inline-block;
  padding: 6px 12px;
  background: var(--green-primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  margin-bottom: 12px;
}

.card__title {
  margin-bottom: 8px;
  color: var(--text-dark);
}

.card__text {
  color: var(--text-medium);
  margin-bottom: 16px;
  font-size: 0.95rem;
}

/* ===== Product Highlights ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.product-card__image {
  width: 100%;
  height: 220px;
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}

.product-card__content {
  padding: 24px;
}

.product-card__title {
  margin-bottom: 8px;
}

.product-card__text {
  color: var(--text-medium);
  font-size: 0.9rem;
  margin-bottom: 16px;
}

/* ===== Promo Section ===== */
.promo {
  background: var(--green-primary);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 60px 40px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.promo--reverse {
  background: var(--cream);
  color: var(--text-dark);
}

.promo__content h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.promo--reverse .promo__content h2 {
  color: var(--green-dark);
}

.promo__content p {
  opacity: 0.9;
  margin-bottom: 24px;
}

.promo__image {
  font-size: 8rem;
  text-align: center;
}

/* ===== Footer ===== */
.footer {
  background: var(--green-dark);
  color: var(--white);
  padding: 60px 0 0;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer__col h4 {
  color: var(--white);
  margin-bottom: 20px;
  font-size: 1rem;
}

.footer__col ul li {
  margin-bottom: 10px;
}

.footer__col a {
  color: rgba(255,255,255,0.7);
  font-size: 0.9rem;
  transition: color var(--transition);
}

.footer__col a:hover {
  color: var(--white);
}

.footer__bottom {
  padding: 24px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer__bottom p {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.6);
}

.footer__social {
  display: flex;
  gap: 16px;
}

.footer__social a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  transition: background var(--transition);
}

.footer__social a:hover {
  background: var(--green-primary);
}

/* ===== Footer Accordion (Mobile) ===== */
.footer__accordion {
  display: none;
}

.footer__accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer__accordion-header {
  width: 100%;
