}

.cookie-banner__text p {
  font-size: 0.9rem;
  color: var(--text-medium);
}

.cookie-banner__actions {
  display: flex;
  gap: 12px;
}

/* ===== Menu Page Styles ===== */
.breadcrumb {
  padding: 20px 0;
  font-size: 0.9rem;
  color: var(--text-medium);
}

.breadcrumb a {
  color: var(--green-primary);
}

.breadcrumb span {
  margin: 0 8px;
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 40px;
  padding: 40px 0;
}

.menu-sidebar {
  position: sticky;
  top: 100px;
