  gap: 12px;
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  color: var(--text-dark);
  font-size: 0.95rem;
  transition: all var(--transition);
}

.menu-sidebar nav a:hover,
.menu-sidebar nav a.active {
