}

.menu-content {
  min-height: 600px;
}

.menu-category {
  margin-bottom: 60px;
}

.menu-category h2 {
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--cream);
}

.menu-items {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}

.menu-item {
  padding: 20px;
  border-radius: var(--radius-md);
  background: var(--white);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.menu-item:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-soft);
}

.menu-item__name {
  font-weight: 600;
  margin-bottom: 4px;
}

.menu-item__desc {
  font-size: 0.85rem;
  color: var(--text-medium);
}

/* ===== Rewards Page Styles ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--green-dark) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}

.rewards-hero h1 {
  color: var(--white);
  margin-bottom: 16px;
}

.rewards-hero p {
  opacity: 0.9;
  max-width: 600px;
  margin: 0 auto;
}

.how-it-works {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
}

.how-step {
  text-align: center;
  padding: 32px;
}

.how-step__number {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--cream);
  color: var(--green-dark);
  font-size: 1.5rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
}

.how-step h3 {
  margin-bottom: 12px;
}

.how-step p {
  color: var(--text-medium);
  font-size: 0.95rem;
}

.status-tiers {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.tier-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  border: 2px solid transparent;
  transition: all var(--transition);
}

.tier-card:hover {
  transform: translateY(-4px);
}

.tier-card--green {
  border-color: var(--green-primary);
}

.tier-card--gold {
  border-color: #D4AF37;
  background: linear-gradient(to bottom, #FFFDF5, var(--white));
}

.tier-card--reserve {
  border-color: #8B7355;
  background: linear-gradient(to bottom, #F5F0EB, var(--white));
}

.tier-card__badge {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

.tier-card--green .tier-card__badge {
  background: var(--green-primary);
}

.tier-card--gold .tier-card__badge {
  background: linear-gradient(135deg, #D4AF37, #FFD700);
}

.tier-card--reserve .tier-card__badge {
  background: linear-gradient(135deg, #8B7355, #A08060);
}

.tier-card__name {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.tier-card__threshold {
  font-size: 0.9rem;
  color: var(--text-medium);
  margin-bottom: 20px;
}

.tier-card ul {
  text-align: left;
}

.tier-card ul li {
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.9rem;
  color: var(--text-medium);
}

.tier-card ul li:last-child {
  border-bottom: none;
}

/* Redemption Tabs */
.redemption-levels {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: 40px;
}

.redemption-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  border-bottom: 2px solid var(--border);
  padding-bottom: 16px;
}

.redemption-tab {
  padding: 12px 24px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-medium);
  background: var(--white);
  border: 2px solid var(--border);
  transition: all var(--transition);
}

.redemption-tab:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.redemption-tab.active {
  background: var(--green-primary);
  color: var(--white);
  border-color: var(--green-primary);
}

.redemption-content {
  display: none;
  animation: fadeIn 0.3s ease;
}

.redemption-content.active {
  display: block;
}

.redemption-content__header {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 24px;
}

.redemption-content__icon {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  box-shadow: var(--shadow-soft);
}

.redemption-content__stars {
  font-size: 2rem;
  font-weight: 700;
  color: var(--green-primary);
}

.redemption-content__reward {
  font-size: 1.2rem;
  color: var(--text-medium);
}

.redemption-items {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 16px;
}

.redemption-item {
  background: var(--white);
  padding: 20px;
  border-radius: var(--radius-md);
  display: flex;
  gap: 16px;
  align-items: center;
  box-shadow: var(--shadow-soft);
}

.redemption-item__emoji {
  font-size: 2rem;
  width: 50px;
  height: 50px;
  background: var(--cream-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.redemption-item__text h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.redemption-item__text p {
  font-size: 0.85rem;
  color: var(--text-medium);
}

.partnerships {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.partnership-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  gap: 20px;
  align-items: center;
  box-shadow: var(--shadow-soft);
}

.partnership-card__icon {
  font-size: 3rem;
  width: 80px;
  height: 80px;
  background: var(--cream-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.partnership-card h3 {
  margin-bottom: 8px;
}

.partnership-card p {
  color: var(--text-medium);
  font-size: 0.9rem;
}

.app-download {
  background: var(--green-dark);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 60px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.app-download__content h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.app-download__content p {
  opacity: 0.9;
  margin-bottom: 24px;
}

.app-download__buttons {
  display: flex;
  gap: 16px;
}

.app-download__visual {
  font-size: 10rem;
  text-align: center;
}

.terms-link {
  text-align: center;
  color: var(--green-primary);
  text-decoration: underline;
}

/* ===== Gift Page Styles ===== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
  padding: 80px 0;
  text-align: center;
}

.gift-hero h1 {
  color: var(--green-dark);
}

.gift-hero p {
  color: var(--text-medium);
  max-width: 600px;
  margin: 16px auto 0;
}

.carousel-section {
  padding: 60px 0;
}

.carousel-section h2 {
  margin-bottom: 24px;
}

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: 20px;
  transition: transform 0.4s ease;
}

.carousel__card {
  flex: 0 0 calc(25% - 15px);
  min-width: 260px;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  transition: all var(--transition);
}

.carousel__card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.carousel__card-image {
  height: 160px;
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--cream) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.carousel__card-content {
  padding: 20px;
}

.carousel__card-content h4 {
  margin-bottom: 4px;
}

.carousel__card-content p {
  font-size: 0.85rem;
  color: var(--text-medium);
}

.carousel__nav {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}

.carousel__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}

.carousel__btn:hover {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.carousel__btn svg {
  width: 20px;
  height: 20px;
}

.business-gifting {
  background: var(--green-primary);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 60px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
}

.business-gifting__content h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.business-gifting__content p {
  opacity: 0.9;
  margin-bottom: 24px;
}

.business-gifting__visual {
  font-size: 8rem;
  text-align: center;
}

.egift-info {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: center;
  padding: 60px 0;
}

.egift-info__visual {
  font-size: 8rem;
  text-align: center;
}

.faq-section {
  max-width: 800px;
  margin: 0 auto;
  padding: 60px 0;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 1.1rem;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  transition: transform var(--transition);
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: 20px;
  color: var(--text-medium);
}

/* ===== Store Locator Styles ===== */
.store-locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  gap: 0;
  min-height: calc(100vh - 72px);
}

.store-search {
  background: var(--cream-light);
  padding: 24px;
  border-right: 1px solid var(--border);
}

.order-type-toggle {
  display: flex;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 6px;
  margin-bottom: 20px;
}

.order-type-toggle button {
  flex: 1;
  padding: 12px;
  border-radius: var(--radius-md);
  font-weight: 600;
  color: var(--text-medium);
  transition: all var(--transition);
}

.order-type-toggle button.active {
  background: var(--green-primary);
  color: var(--white);
}

.search-input-wrapper {
  position: relative;
  margin-bottom: 16px;
}

.search-input-wrapper input {
  width: 100%;
  padding: 14px 16px 14px 44px;
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 1rem;
  transition: border-color var(--transition);
}

.search-input-wrapper input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.search-input-wrapper svg {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--text-light);
}

.filter-btn {
  width: 100%;
  padding: 12px;
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-weight: 600;
  color: var(--text-dark);
  margin-bottom: 20px;
  transition: all var(--transition);
}

.filter-btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.filter-panel {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 20px;
  display: none;
}

.filter-panel.show {
  display: block;
}

.filter-group {
  margin-bottom: 16px;
}

.filter-group:last-child {
  margin-bottom: 0;
}

.filter-group label {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  cursor: pointer;
}

.filter-group input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

.store-results {
  padding: 24px;
}

.store-count {
  font-size: 0.9rem;
  color: var(--text-medium);
  margin-bottom: 16px;
}

.store-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 20px;
  margin-bottom: 12px;
  cursor: pointer;
  transition: all var(--transition);
}

.store-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-soft);
}

.store-card.active {
  border-color: var(--green-primary);
  background: rgba(0, 130, 74, 0.05);
}

.store-card__name {
  font-weight: 600;
  margin-bottom: 4px;
}

.store-card__address {
  font-size: 0.9rem;
  color: var(--text-medium);
  margin-bottom: 8px;
}

.store-card__hours {
  font-size: 0.85rem;
  color: var(--text-light);
  margin-bottom: 8px;
}

.store-card__features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.store-card__feature {
  padding: 4px 10px;
  background: var(--cream-light);
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  color: var(--text-medium);
}

.store-map {
  height: 100%;
  min-height: 500px;
  background: var(--cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.store-map__placeholder {
  text-align: center;
  color: var(--text-medium);
}

.store-map__placeholder svg {
  width: 80px;
  height: 80px;
  margin-bottom: 16px;
  color: var(--green-primary);
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 40px;
  cursor: pointer;
  transition: transform var(--transition);
}

.map-pin:hover {
  transform: scale(1.2);
}

/* ===== Animations ===== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .menu-layout {
    grid-template-columns: 220px 1fr;
  }

  .carousel__card {
    flex: 0 0 calc(33.333% - 14px);
  }

  .store-locator-layout {
    grid-template-columns: 350px 1fr;
  }
}

@media (max-width: 900px) {
  .promo,
  .app-download,
  .business-gifting,
  .egift-info {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .promo__image,
  .app-download__visual,
  .business-gifting__visual,
  .egift-info__visual {
    display: none;
  }

  .how-it-works,
  .status-tiers,
  .partnerships {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    display: none;
  }

  .footer__accordion {
    display: block;
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    padding-bottom: 20px;
    border-bottom: 1px solid var(--border);
  }

  .menu-sidebar__title {
    display: none;
  }

  .menu-sidebar__section {
    display: flex;
    gap: 8px;
    margin-bottom: 0;
  }

  .menu-sidebar nav a {
    padding: 8px 12px;
    font-size: 0.85rem;
  }

  .store-locator-layout {
    grid-template-columns: 1fr;
  }

  .store-map {
    min-height: 300px;
    order: -1;
  }

  .carousel__card {
    flex: 0 0 calc(50% - 10px);
  }
}

@media (max-width: 600px) {
  .section {
    padding: 60px 0;
  }

  .header__nav {
    display: none;
  }

  .header__menu-btn {
    display: flex;
  }

  .hero {
    padding: 60px 0;
  }

  .product-grid {
    grid-template-columns: 1fr;
  }

  .redemption-tabs {
    justify-content: center;
  }

  .redemption-tab {
    padding: 10px 16px;
    font-size: 0.85rem;
  }

  .carousel__card {
    flex: 0 0 calc(100% - 20px);
  }

  .app-download,
  .business-gifting {
    padding: 40px 24px;
  }

  .footer__bottom {
    flex-direction: column;
    text-align: center;
